	staged.spool(GenerationConfigFile("controller-a"), staged.config)
	for name, data := range staged.files {
		staged.spool(name, data)
	}
	if err := os.WriteFile(staged.installer.config, []byte(oldConfig), 0o644); err != nil {
		t.Fatal(err)
	}
	return staged
