func (staged *spooledInstall) spool(name string, data []byte) {
	staged.t.Helper()
	if err := os.WriteFile(filepath.Join(staged.installer.spool, name), data, 0o600); err != nil {
		staged.t.Fatal(err)
	}
}

func (staged *spooledInstall) arm() {
	staged.spool(GenerationArmedFile, []byte(staged.fingerprint+"\n"))
}

func (staged *spooledInstall) pending() string {
	return filepath.Join(filepath.Dir(staged.installer.config), pendingControllerConfig)
}

func (staged *spooledInstall) install() string {
	staged.t.Helper()
	outcome, err := staged.installer.install(time.Now())
	if err != nil {
		staged.t.Fatal(err)
	}
	return outcome
}

func (install *generationInstall) store() MaterialStore {
	return MaterialStore{installedDirectory: install.dir, serviceUID: uint32(os.Getuid()),
		serviceGID: uint32(os.Getgid()), allowUnsafeAncestors: true}
}

// stage writes a stage as a crash would leave it.
func (install *generationInstall) stage(files map[string][]byte) {
	install.t.Helper()
	staging := filepath.Join(install.dir, generationStaging)
	if err := os.Mkdir(staging, 0o700); err != nil && !os.IsExist(err) {
		install.t.Fatal(err)
	}
	for name, content := range files {
		if err := os.WriteFile(filepath.Join(staging, name), content, 0o600); err != nil {
			install.t.Fatal(err)
		}
	}
