func VerifyAcceptedIdentityCheckpoint(wire []byte, genesis trust.Keyring, chain trust.RootChain,
	expected CheckpointExpectation, now time.Time,
) (VerifiedIdentityCheckpoint, error) {
	if len(wire) == 0 || len(wire) > MaxCheckpointWireBytes {
		return VerifiedIdentityCheckpoint{}, fmt.Errorf("%w: wire size", ErrCheckpointInvalid)
	}
	if !validIdentity(expected.OperationID, expected.DeploymentID, expected.ClusterID, expected.Environment, expected.Cell) ||
		!digestRE.MatchString(expected.MaterialGenerationSHA256) || expected.Broker.validate() != nil ||
		expected.Slot.validate(expected.Cell, true) != nil {
		return VerifiedIdentityCheckpoint{}, fmt.Errorf("%w: expectation", ErrCheckpointInvalid)
	}
	envelope, err := trust.DecodeEnvelope(wire)
	if err != nil {
		return VerifiedIdentityCheckpoint{}, err
	}
	roots, err := trust.VerifyRootChain(genesis, trust.ChainIdentity{DeploymentID: expected.DeploymentID,
		Cell: strings.ToLower(expected.Cell), Environment: expected.Environment}, chain)
	if err != nil {
		return VerifiedIdentityCheckpoint{}, err
	}
	identity := AcceptedIdentityCheckpoint{OperationID: expected.OperationID, DeploymentID: expected.DeploymentID,
		ClusterID: expected.ClusterID, Environment: expected.Environment, Cell: expected.Cell}
	payload, err := trust.VerifyCurrent(envelope, identity.scope(), roots.Current, now,
		trust.Policy{MaxLifetime: MaxCheckpointLifetime})
	if err != nil {
		return VerifiedIdentityCheckpoint{}, err
	}
	var checkpoint AcceptedIdentityCheckpoint
	if err := protocol.DecodeStrict(payload, &checkpoint, MaxCheckpointBytes); err != nil {
		return VerifiedIdentityCheckpoint{}, err
	}
	if err := checkpoint.Validate(); err != nil {
		return VerifiedIdentityCheckpoint{}, err
	}
	canonical, err := trust.EncodePayload(checkpoint)
	if err != nil || !bytes.Equal(canonical, payload) {
		return VerifiedIdentityCheckpoint{}, fmt.Errorf("%w: noncanonical payload", ErrCheckpointInvalid)
	}
	if checkpoint.OperationID != expected.OperationID || checkpoint.DeploymentID != expected.DeploymentID ||
		checkpoint.ClusterID != expected.ClusterID || checkpoint.Environment != expected.Environment ||
		checkpoint.Cell != expected.Cell || checkpoint.SeedSlot != expected.SeedSlot ||
		(checkpoint.ManagedMaterial == nil) != (expected.ManagedMaterial == nil) ||
		checkpoint.ManagedMaterial != nil && *checkpoint.ManagedMaterial != *expected.ManagedMaterial ||
		checkpoint.MaterialGenerationSHA256 != expected.MaterialGenerationSHA256 ||
		checkpoint.Broker != expected.Broker {
		return VerifiedIdentityCheckpoint{}, ErrCheckpointMismatch
	}
	for _, binding := range checkpoint.Slots {
		if binding.Slot != expected.Slot.Slot {
			continue
		}
		want, err := trust.EncodePayload(expected.Slot)
		got, gotErr := trust.EncodePayload(binding)
		if err != nil || gotErr != nil || !bytes.Equal(want, got) {
			return VerifiedIdentityCheckpoint{}, ErrCheckpointMismatch
		}
		return VerifiedIdentityCheckpoint{checkpoint: checkpoint, wire: bytes.Clone(wire),
			fingerprint: sha256Hex(wire), slot: expected.Slot.Slot, expiresAt: envelope.ExpiresAt, verified: true}, nil
	}
	return VerifiedIdentityCheckpoint{}, ErrCheckpointMismatch
}

func VerifyHostStateHandoffPlan(envelope trust.Envelope, currentRoots trust.Keyring, observed HostStateObservation, now time.Time) (VerifiedHostStateHandoffPlan, error) {
	expected, err := BuildHostStateHandoffPlan(observed, now)
	if err != nil {
		return VerifiedHostStateHandoffPlan{}, err
	}
	payload, err := trust.VerifyCurrent(envelope, expected.scope(), currentRoots, now, trust.Policy{MaxLifetime: time.Hour})
	if err != nil {
		return VerifiedHostStateHandoffPlan{}, err
	}
	var plan HostStateHandoffPlan
	if err := protocol.DecodeStrict(payload, &plan, MaxHostStatePlanBytes); err != nil {
		return VerifiedHostStateHandoffPlan{}, err
	}
	want, err := trust.EncodePayload(expected)
	if err != nil || !bytes.Equal(payload, want) {
		return VerifiedHostStateHandoffPlan{}, fmt.Errorf("%w: root plan differs from independent facts or canonical bytes", ErrHostStateHandoff)
	}
	return VerifiedHostStateHandoffPlan{plan: plan, fingerprint: sha256Hex(payload), verified: true}, nil
}

func VerifyRootChain(genesis Keyring, id ChainIdentity, chain RootChain) (VerifiedRoots, error) {
	if chain.Version != 1 || len(genesis) == 0 || len(genesis) > MaxRootSet || len(chain.Rotations) > MaxRotations {
		return VerifiedRoots{}, fmt.Errorf("%w: root chain genesis or length", ErrInvalid)
	}
	if err := RotationScope(id, 1).validate(); err != nil {
		return VerifiedRoots{}, err
	}
	verified := VerifiedRoots{Current: maps.Clone(genesis), Historical: maps.Clone(genesis), Head: RootSetDigest(genesis)}
	for index, signed := range chain.Rotations {
		next, payload, err := verifyRotation(signed, id, verified)
		if err != nil {
			return VerifiedRoots{}, fmt.Errorf("root rotation %d: %w", index+1, err)
		}
		sum := sha256.Sum256(payload)
		verified.Current, verified.Sequence, verified.Head = next, verified.Sequence+1, hex.EncodeToString(sum[:])
		maps.Copy(verified.Historical, next)
	}
	return verified, nil
}

func SignIdentityReset(reset IdentityReset, issuedAt, expiresAt time.Time, key ed25519.PrivateKey) (trust.Envelope, error) {
	if err := reset.Validate(); err != nil {
		return trust.Envelope{}, err
	}
	if expiresAt.Sub(issuedAt) > identityResetPolicy.MaxLifetime {
		return trust.Envelope{}, errors.New("identity reset authority exceeds one hour")
	}
	payload, err := trust.EncodePayload(reset)
	if err != nil {
		return trust.Envelope{}, err
	}
	if len(payload) > maxIdentityResetBytes {
		return trust.Envelope{}, errors.New("identity reset exceeds bounded root pin payload")
	}
	return trust.Sign(payload, reset.trustScope(), issuedAt, expiresAt, key)
}

func VerifyIdentityReset(envelope trust.Envelope, roots trust.Keyring, target IdentityResetTarget, now time.Time) (IdentityReset, error) {
	if target.Replicas < 1 || target.Replicas > 5 || target.Replicas%2 == 0 {
		return IdentityReset{}, errors.New("identity reset requires an existing odd replica quorum")
	}
	expected := IdentityReset{DeploymentID: target.DeploymentID, Scope: target.Scope, Environment: target.Environment}
	payload, err := trust.VerifyCurrent(envelope, expected.trustScope(), roots, now, identityResetPolicy)
	if err != nil {
		return IdentityReset{}, fmt.Errorf("verify root-signed identity reset: %w", err)
	}
	var reset IdentityReset
	if err := protocol.DecodeStrict(payload, &reset, maxIdentityResetBytes); err != nil {
		return IdentityReset{}, err
	}
	if err := reset.Validate(); err != nil {
		return IdentityReset{}, err
	}
	canonical, err := trust.EncodePayload(reset)
	if err != nil || !bytes.Equal(payload, canonical) {
		return IdentityReset{}, errors.New("identity reset payload must be canonical v1 JSON")
	}
	if reset.OperationID != target.OperationID || reset.DeploymentID != target.DeploymentID ||
		reset.ClusterID != target.ClusterID || reset.Scope != target.Scope || reset.Environment != target.Environment ||
		reset.CheckpointSHA256 != target.CheckpointSHA256 || reset.HostStatePlanSHA256 != target.HostStatePlanSHA256 {
		return IdentityReset{}, trust.ErrScopeMismatch
	}
	return reset, nil
}

